const G=42;
const P=/^(dirt_path|coarse_dirt|gravel|moss_block)$/;
let n=0;
voxel.part('Paths',()=>{
  for(let x=24;x<=140;x++)for(let z=18;z<=146;z++){
    if(voxel.get(x,G,z)!=='air')continue; const id=voxel.get(x,G-1,z); if(!P.test(id))continue;
    let sides=0; for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){ const b=voxel.get(x+dx,G,z+dz); if(b!=='air'||P.test(voxel.get(x+dx,G-1,z+dz))) sides++; }
    if(sides<3)continue;
    voxel.block(x,G,z,id); voxel.block(x,G-1,z,'dirt'); n++;
  }
});
